package cl.bancoxyz.account;
import org.springframework.context.annotation.*;import org.springframework.security.config.Customizer;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.config.http.SessionCreationPolicy;import org.springframework.security.web.SecurityFilterChain;
@Configuration public class SecurityConfig {@Bean SecurityFilterChain security(HttpSecurity http)throws Exception{return http.csrf(c->c.disable()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/actuator/health","/actuator/health/**").permitAll().requestMatchers(org.springframework.http.HttpMethod.GET,"/api/accounts/**").hasAnyAuthority("SCOPE_bank.read","SCOPE_atm.read").requestMatchers("/api/accounts/**").hasAnyAuthority("SCOPE_bank.write","SCOPE_atm.write").anyRequest().denyAll()).oauth2ResourceServer(o->o.jwt(Customizer.withDefaults())).build();}}
